```kotlin
fun registerUser(name: String, email: String, age: Int): List<String> {
    val errors = mutableListOf<String>()

    // دالة محلية محصورة داخل سياق registerUser وتصل للمتغيرات مباشرة
    fun validate(condition: Boolean, message: String) {
        if (!condition) errors.add(message)
    }

    validate(name.isNotBlank(), "Name cannot be empty")
    validate(email.contains("@"), "Email must contain @")
    validate(age >= 18, "Age must be at least 18")

    return errors
}
```
