```kotlin
inline fun <T> measureExecution(tag: String, block: () -> T): T {
    val start = System.currentTimeMillis()
    try {
        return block()
    } finally {
        val duration = System.currentTimeMillis() - start
        println("[$tag] took ${duration}ms")
    }
}

fun main() {
    // في مكان الاستدعاء: يتم نسخ الكود بالكامل بدون إنشاء أي كائن Function
    val total = measureExecution("Sum Calculation") {
        (1..1000).sum()
    }
}
```
في هذا الكود، تم إلغاء تكلفة حجز الـ Function Object تماماً في الـ Heap بفضل الـ inlining.

KOT-13.worked_example_ar:
يوضح المثال التالي تكامل المفاهيم الأربعة في دالة أندرويد متقدمة:
```kotlin
inline fun <reified T : Activity> Context.startAndTrack(
    crossinline onAsyncDone: () -> Unit,
    noinline errorCallback: (Throwable) -> Unit
) {
    // 1. reified: استخدام نوع الكلاس مباشرة وقت التشغيل
    val intent = Intent(this, T::class.java)
    startActivity(intent)

    // 2. crossinline: تنفيذ اللامبدا في سياق غير متزامن بدون non-local return
    Handler(Looper.getMainLooper()).post {
        onAsyncDone()
    }

    // 3. noinline: تخزين اللامبدا ككائن في مسجل الأخطاء
    ErrorRegistry.register(errorCallback)
}
```
هذا التصميم يجمع بين سرعة الـ Inlining وأمان التزامن ومرونة تخزين الكول باكس.

KOT-14.worked_example_ar:
يوضح المثال التالي الفرق العملي بين المنتج المشترك (out) والمستهلك المعاكس (in):
```kotlin
open class Animal
class Dog : Animal()

// 1. Covariance (out): تنتج T فقط (Producer)
interface Source<out T> {
    fun produce(): T
}

// 2. Contravariance (in): تستهلك T فقط (Consumer)
interface Sink<in T> {
    fun consume(item: T)
}

fun main() {
    val dogSource: Source<Dog> = object : Source<Dog> { override fun produce() = Dog() }
    // مسموح: Source<Dog> تعتبر Subtype من Source<Animal>
    val animalSource: Source<Animal> = dogSource

    val animalSink: Sink<Animal> = object : Sink<Animal> { override fun consume(item: Animal) {} }
    // مسموح: Sink<Animal> تعتبر Subtype من Sink<Dog>
    val dogSink: Sink<Dog> = animalSink
}
```
هذا التقسيم يضمن عدم تمرير كائنات خاطئة للذاكرة مع إتاحة المرونة الكاملة.

