```kotlin
interface AnalyticsService {
    fun logEvent(name: String)
    fun setUserId(id: String)
}

// 1. Interface Delegation: تفويض الواجهة مع تعديل سلوك دالة معينة
class DecoratedAnalytics(
    private val delegate: AnalyticsService
) : AnalyticsService by delegate {
    override fun logEvent(name: String) {
        println("Tracking event: $name")
        delegate.logEvent(name) // توجيه مخصص
    }
    // دالة setUserId يتم تفويضها تلقائياً بدون كتابة أي كود!
}

// 2. Property Delegation: تفويض الخاصية للمراقبة
class UserSession {
    var token: String by Delegates.observable("empty") { prop, old, new ->
        println("Token updated from $old to $new")
    }
}
```
هذا الأسلوب يوفر مئات أسطر الكود الروتيني ويفصل مسؤوليات النظام بوضوح.
